// scripts/setup/provider-setup.mjs — setup's provider step: the catalogue cache, generated by ai-lab under
// cc-config's own interpreter (scripts/shared/own-python.mjs) and written to ~/.claude/provider-cache.json
// (scripts/shared/provider-cache.mjs).

import { spawnSync } from 'child_process';
import { PROVIDER_CACHE_PATH, writeProviderCache } from '../shared/provider-cache.mjs';
import { ownPython } from '../shared/own-python.mjs';

/** Regenerate the provider cache. @returns {{ok:true, providers:number, python:string} | {error:string}} */
export function refreshProviderCache({ python = ownPython(), path = PROVIDER_CACHE_PATH, run = spawnSync } = {}) {
  return writeProviderCache({ python, path, run });
}
